from collections import Counter
from math import ceil


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}
    rectangles = []

    for color in colors:
        same = [[0] * (w + 1) for _ in range(h + 1)]
        occupied = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            same_run = occupied_run = 0
            for c in range(w):
                same_run += grid[r][c] == color
                occupied_run += grid[r][c] != bg
                same[r + 1][c + 1] = same[r][c + 1] + same_run
                occupied[r + 1][c + 1] = occupied[r][c + 1] + occupied_run

        def count(prefix, top, bottom, left, right):
            return (prefix[bottom + 1][right + 1] - prefix[top][right + 1]
                    - prefix[bottom + 1][left] + prefix[top][left])

        candidates = []
        for top in range(h):
            for bottom in range(top + 1, h):
                for left in range(w):
                    for right in range(left + 1, w):
                        area = (bottom - top + 1) * (right - left + 1)
                        n = count(same, top, bottom, left, right)
                        if (count(occupied, top, bottom, left, right) == area
                                and n >= ceil(0.75 * area)):
                            candidates.append((area, n, top, bottom, left, right, color))

        candidates.sort(reverse=True)
        maximal = []
        for item in candidates:
            _, _, top, bottom, left, right, _ = item
            if any(top >= a and bottom <= b and left >= c and right <= d
                   for _, _, a, b, c, d, _ in maximal):
                continue
            maximal.append(item)
        rectangles.extend(maximal)

    rectangles.sort(reverse=True)
    selected = []
    for item in rectangles:
        _, _, top, bottom, left, right, _ = item
        if any(not (bottom < a or b < top or right < c or d < left)
               for _, _, a, b, c, d, _ in selected):
            continue
        selected.append(item)

    output = [[bg] * w for _ in range(h)]
    for _, _, top, bottom, left, right, color in selected:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                output[r][c] = color
    return output

